import cues from '../../audio/first_light/cues.json';
import {createTimeline} from '../timeline';

/**
 * The first_light timeline, generated by tools/build_space_audio.py
 * (--episode first_light) from audio/first_light/story.json.
 */
export type Cue = keyof typeof cues.events;

export const timeline = createTimeline<Cue>(cues.events as Record<Cue, number>, cues.bpm);
export const {at, syncTo, playUntil, beat} = timeline;
export const duration = cues.duration;
